#include "ogles2.h"

/*
 * ogles3.library (docs/phase10-ogles3.md): ogles2.library's sources built
 * against the ogles3 SDK (QT_OGLES3), with the entries OpenGL ES 3.x adds
 * in this directory. One entry point (LVO -30) returns the dispatch table
 * (dispatch.auto.c, generated by ogles2.library/oglesgen.py --ogles3).
 */

extern const struct OGLES3Dispatch ogles2_dispatch;

void INIT_0_OGLES3(void) {
	glInit();
}

void EXIT_0_OGLES3(void) {
	glExit();
}

const struct OGLES3Dispatch *OGLES3GetDispatchTable(void) {
	return &ogles2_dispatch;
}

/* LVO -36 (ogles3.fd): called by the SDK's OGLES3Close() before
 * CloseLibrary. Nothing to flush here. */
void OGLES3PrivateLogFlush(void) {}
